#include <Arduino.h>

// XIAO ESP32S3 の内蔵LEDピン
#define LED_PIN 2

void setup() {
  // パソコンとのUSB接続の挙動を安定させるための初期化
  Serial.begin(115200);

  // LEDピンを出力モードに設定
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  digitalWrite(LED_PIN, LOW);  // LEDを点灯 (XIAOはLOWで光ります)
  delay(500);                  // 0.5秒待機

  digitalWrite(LED_PIN, HIGH); // LEDを消灯
  delay(500);                  // 0.5秒待機
}
